sys_script_client.script:
function onLoad() {

    // Don't show instructions if the Catalog Task is already Closed Complete
    if (g_form.getValue('state') == '3') {
        return;
    }

    var taskNum = g_form.getValue('number');

    g_form.addErrorMessage(
        '<b>⚠️ ACTION REQUIRED:</b><br><br>' +
        '1. Manually create a <b>Jira Story</b> on the Jira board using the requirements and details provided in the <b>Description</b> field.<br><br>' +
        '2. While creating the Jira Story, make sure the Jira <b>Description</b> includes:<br>' +
        '<b>Ref: ' + taskNum + '</b><br><br>' +
        '3. After the Jira Story is created, copy the generated <b>Jira Issue Key</b> (for example, SCRUM-123) and enter it in the <b>Jira Issue Key</b> field on this Catalog Task.<br><br>' +
        '4. Once the Jira Issue Key has been entered, you can close this Catalog Task.'
    );

    g_form.setDisabled('short_description', true);
    g_form.setDisabled('description', true);
}
